package live.linghe.privateinput;

import android.content.Context;import java.io.*;import java.math.BigInteger;import java.util.*;import java.util.function.BooleanSupplier;import org.json.*;

/** Authenticated opt-in recency lane; a missing endpoint never disables existing v1 sync. */
final class RecentLearningSync {
 interface Transport{JSONObject post(String path,JSONObject request)throws Exception;}
 interface Save{void run()throws Exception;}
 private final Context context;private final JSONObject state,membership,identity;private final RecentLearningStore store;private final Transport transport;private final BooleanSupplier consent;private final Save save;
 private final String group,sender,binding;private final BigInteger epoch,revision;
 RecentLearningSync(Context context,JSONObject state,Transport transport,BooleanSupplier consent,Save save)throws Exception{
  this.context=context;this.state=state;this.transport=transport;this.consent=consent;this.save=save;membership=state.getJSONObject("membership");identity=state.getJSONObject("identity");group=SyncCrypto.id(membership.getString("group"));sender=SyncCrypto.id(identity.getString("device"));epoch=SyncCrypto.u(membership,"epoch");revision=SyncCrypto.u(membership,"revision");binding=group+"/"+epoch+"/"+revision;store=new RecentLearningStore(context.getFilesDir());
 }
 private void allowed()throws Exception{SyncCrypto.require(consent.getAsBoolean()&&(SyncCrypto.find(membership,sender).getInt("permissions")&1)!=0&&SyncCrypto.id(state.getJSONObject("membership").getString("group")).equals(group)&&SyncCrypto.u(state.getJSONObject("membership"),"epoch").equals(epoch));}
 private JSONObject call(int op,JSONObject body)throws Exception{
  allowed();byte[] encoded=SyncCrypto.bytes(LosslessJson.canonical(body));String nonce=SyncCrypto.id();long now=System.currentTimeMillis()/1000;JSONObject request=new JSONObject().put("version",1).put("group",group).put("sender",sender).put("nonce",nonce).put("issuedAt",now).put("operation",op).put("body",SyncCrypto.b64(encoded));request.put("signature",SyncCrypto.b64(SyncCrypto.sign(RecentLearningWire.request(group,sender,nonce,BigInteger.valueOf(now),op,encoded),SyncCrypto.privateKey("Ed25519",identity.getString("signing")))));
  RecentLearningStore.Usage start=RecentLearningStore.usage(context);JSONObject result=transport.post("/v1/groups/"+group+"/recency",request);RecentLearningStore.Usage end=RecentLearningStore.usage(context);allowed();
  SyncCrypto.require(SyncCrypto.u(result,"version").equals(BigInteger.ONE)&&SyncCrypto.id(result.getString("group")).equals(group)&&SyncCrypto.id(result.getString("sender")).equals(sender)&&SyncCrypto.id(result.getString("nonce")).equals(nonce)&&SyncCrypto.u(result,"epoch").equals(epoch)&&SyncCrypto.u(result,"membershipRevision").equals(revision)&&result.get("ready") instanceof Boolean&&start.bootSession.equals(end.bootSession)&&end.uptime>=start.uptime&&end.uptime-start.uptime<=10);
  double server=SyncCrypto.u(result,"serverTime").doubleValue();int day=SyncCrypto.u(result,"referenceDay").intValueExact();SyncCrypto.require(server<=259200000000.0&&Math.abs(server-now)<300&&Math.floor(server/86400)==day);JSONArray missing=result.getJSONArray("missing");SyncCrypto.require(missing.length()<=64&&(!result.getBoolean("ready")||missing.length()==0));Set<String> seen=new HashSet<>();for(int i=0;i<missing.length();i++){String member=SyncCrypto.id(missing.getString(i));SyncCrypto.find(membership,member);SyncCrypto.require(seen.add(member));}
  store.acceptAuthenticatedPolicy(new RecentLearningStore.PolicyState(binding,new RecentLearning.Policy(day),new RecentLearning.Clock(server,end.uptime,end.bootSession),result.getBoolean("ready")));return result;
 }
 private JSONObject body()throws Exception{return new JSONObject().put("epoch",epoch).put("membershipRevision",revision);}
 private static byte[] header(JSONObject wire)throws Exception{SyncCrypto.require(SyncCrypto.u(wire,"version").equals(BigInteger.ONE));return RecentLearningWire.header(wire.getString("group"),wire.getString("sender"),wire.getString("event"),SyncCrypto.u(wire,"epoch"),SyncCrypto.u(wire,"issuedAt"),SyncCrypto.u(wire,"expiresAt"));}
 private byte[] key(JSONObject wire)throws Exception{JSONObject member=SyncCrypto.find(membership,wire.getString("sender"));SyncCrypto.require((member.getInt("permissions")&1)!=0&&SyncCrypto.id(wire.getString("group")).equals(group)&&SyncCrypto.u(wire,"epoch").equals(epoch));byte[] master=SyncCrypto.data(state,"groupKey");SyncCrypto.require(master.length==32);return SyncCrypto.hkdf(master,RecentLearningWire.salt(group,epoch),RecentLearningWire.info(wire.getString("sender"),SyncCrypto.data(member,"signingPublic")));}
 private JSONObject seal(String payload,long serverNow)throws Exception{byte[] bytes=SyncCrypto.bytes(payload);SyncCrypto.require(bytes.length<=RecentLearningStore.MAX_BYTES);JSONObject wire=new JSONObject().put("version",1).put("group",group).put("sender",sender).put("event",SyncCrypto.id()).put("epoch",epoch).put("issuedAt",serverNow).put("expiresAt",serverNow+7*86400);byte[] header=header(wire),nonce=SyncCrypto.random(12),sealed=SyncCrypto.concat(nonce,SyncCrypto.chacha(true,key(wire),nonce,header,bytes));return wire.put("sealed",SyncCrypto.b64(sealed)).put("signature",SyncCrypto.b64(SyncCrypto.sign(SyncCrypto.concat(header,sealed),SyncCrypto.privateKey("Ed25519",identity.getString("signing")))));}
 private String open(JSONObject wire,long serverNow)throws Exception{byte[] header=header(wire),sealed=SyncCrypto.data(wire,"sealed");SyncCrypto.require(sealed.length>=28&&sealed.length<=RecentLearningStore.MAX_BYTES+28&&SyncCrypto.u(wire,"issuedAt").compareTo(BigInteger.valueOf(serverNow+300))<=0&&SyncCrypto.u(wire,"expiresAt").compareTo(BigInteger.valueOf(serverNow))>0);byte[] key=key(wire);SyncCrypto.verify(SyncCrypto.concat(header,sealed),SyncCrypto.data(wire,"signature"),SyncCrypto.data(SyncCrypto.find(membership,wire.getString("sender")),"signingPublic"));return SyncCrypto.utf8(SyncCrypto.chacha(false,key,Arrays.copyOfRange(sealed,0,12),header,Arrays.copyOfRange(sealed,12,sealed.length)));}
 private void remember(JSONObject wire,long serverNow)throws Exception{store.acceptReceipt(binding,SyncCrypto.id(wire.getString("event")),SyncCrypto.b64(SyncCrypto.sha(SyncCrypto.concat(header(wire),SyncCrypto.data(wire,"sealed")))),SyncCrypto.u(wire,"expiresAt").longValueExact(),serverNow);}
 private void mergeEnvelope(JSONObject envelope,long serverNow)throws Exception{String incoming=open(envelope,serverNow);allowed();remember(envelope,serverNow);RecentLearningStore.Snapshot merged=store.mergeAuthenticatedArchive(incoming,binding);allowed();String projection=RecentLearningStore.legacyProjection(merged);new LearningSnapshotFile(new File(context.getFilesDir(),"Shared")).publish(projection);if(merged.personal!=null)new PersonalLexicon(new File(context.getFilesDir(),"Shared")).mergeSynchronized(merged.personal.synchronizationObject().toString());}
 private void markPublication(String digest,long time)throws Exception{boolean hadDigest=state.has("recencyPublishedDigest"),hadTime=state.has("recencyPublishedAt");Object oldDigest=state.opt("recencyPublishedDigest"),oldTime=state.opt("recencyPublishedAt");state.put("recencyPublishedDigest",digest).put("recencyPublishedAt",time);try{save.run();}catch(Exception failure){if(hadDigest)state.put("recencyPublishedDigest",oldDigest);else state.remove("recencyPublishedDigest");if(hadTime)state.put("recencyPublishedAt",oldTime);else state.remove("recencyPublishedAt");throw failure;}}
 void synchronize()throws Exception{
  try{
   JSONObject hello=call(1,body().put("roles",new JSONArray().put("app").put("keyboard")));if(!hello.getBoolean("ready"))return;
   LearningCoordinator coordinator=new LearningCoordinator(context.getFilesDir(),new File(context.getFilesDir(),"Shared"));if(coordinator.requiresPrivateRecovery())return;
   long serverNow=SyncCrypto.u(hello,"serverTime").longValueExact();SyncCrypto.require(hello.has("envelope"));JSONObject own=hello.isNull("envelope")?null:hello.getJSONObject("envelope");RecentLearningSlot slot=new RecentLearningSlot(hello.getString("publishedEvent"),own==null?null:own.getString("event"),sender,own==null?null:own.getString("sender"));if(own!=null)mergeEnvelope(own,serverNow);
   String legacy=new LearningSnapshotFile(new File(context.getFilesDir(),"Shared")).read();if(legacy!=null)store.mergeLegacy(legacy);String archive=store.outbound(binding),digest=binding+"/"+SyncCrypto.b64(SyncCrypto.sha(SyncCrypto.bytes(archive)));
   long published=state.optLong("recencyPublishedAt",0);if(slot.shouldPush(digest,state.optString("recencyPublishedDigest"),published,serverNow)){JSONObject envelope=seal(archive,serverNow);JSONObject pushed=call(2,body().put("expectedEvent",slot.publishedEvent).put("envelope",envelope));SyncCrypto.require(pushed.getBoolean("ready")&&pushed.get("accepted") instanceof Boolean&&pushed.getBoolean("accepted")&&slot.accepted(pushed.getString("event"),envelope.getString("event"))&&slot.accepted(pushed.getString("publishedEvent"),envelope.getString("event")));allowed();markPublication(digest,SyncCrypto.u(pushed,"serverTime").longValueExact());}
   String after="";Set<String> seen=new HashSet<>();for(int i=0;i<64;i++){JSONObject pulled=call(3,body().put("after",after));if(!pulled.getBoolean("ready"))return;String next=pulled.getString("next");if(pulled.has("envelope")&&!pulled.isNull("envelope")){JSONObject envelope=pulled.getJSONObject("envelope");String peer=SyncCrypto.id(envelope.getString("sender"));SyncCrypto.require(!peer.equals(sender)&&!next.isEmpty()&&SyncCrypto.id(next).equals(peer)&&seen.add(peer)&&(after.isEmpty()||peer.compareToIgnoreCase(after)>0));mergeEnvelope(envelope,SyncCrypto.u(pulled,"serverTime").longValueExact());}
    else SyncCrypto.require(next.isEmpty());if(next.isEmpty())break;after=SyncCrypto.id(next);
   }
  }catch(Exception unavailable){store.suspendPolicy();throw unavailable;}finally{PersonalChangeSignal.notifyChanged(context);}
 }
}
